// Simple Asteroid Escape game
const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d');
const WIDTH = canvas.width;
const HEIGHT = canvas.height;

// Player ship
const ship = {
  width: 30,
  height: 30,
  x: WIDTH / 2 - 15,
  y: HEIGHT - 40,
  speed: 5,
  moveLeft: false,
  moveRight: false,
  draw() {
    ctx.fillStyle = '#0f0';
    ctx.beginPath();
    ctx.moveTo(this.x, this.y + this.height);
    ctx.lineTo(this.x + this.width / 2, this.y);
    ctx.lineTo(this.x + this.width, this.y + this.height);
    ctx.closePath();
    ctx.fill();
  },
  update() {
    if (this.moveLeft) this.x = Math.max(0, this.x - this.speed);
    if (this.moveRight) this.x = Math.min(WIDTH - this.width, this.x + this.speed);
  }
};

// Asteroids
const asteroids = [];
let asteroidTimer = 0;
const spawnInterval = 90; // frames
let gameOver = false;
let startTime = null;
let score = 0;

function spawnAsteroid() {
  const radius = Math.random() * 15 + 10;
  const x = Math.random() * (WIDTH - radius * 2) + radius;
  const speed = Math.random() * 2 + 1;
  asteroids.push({ x, y: -radius, radius, speed });
}

function updateAsteroids() {
  for (let i = asteroids.length - 1; i >= 0; i--) {
    const a = asteroids[i];
    a.y += a.speed;
    if (a.y - a.radius > HEIGHT) {
      asteroids.splice(i, 1);
    } else if (checkCollision(a)) {
      gameOver = true;
    }
  }
}

function checkCollision(a) {
  // simple AABB vs circle approximation
  const cx = ship.x + ship.width / 2;
  const cy = ship.y + ship.height / 2;
  const dx = Math.abs(a.x - cx);
  const dy = Math.abs(a.y - cy);
  if (dx > (ship.width / 2 + a.radius)) return false;
  if (dy > (ship.height / 2 + a.radius)) return false;
  return true;
}

function drawAsteroids() {
  ctx.fillStyle = '#888';
  asteroids.forEach(a => {
    ctx.beginPath();
    ctx.arc(a.x, a.y, a.radius, 0, Math.PI * 2);
    ctx.fill();
  });
}

function drawScore() {
  ctx.fillStyle = '#fff';
  ctx.font = '16px sans-serif';
  ctx.fillText(`Score: ${Math.floor(score)}`, 10, 20);
}

function loop(timestamp) {
  if (!startTime) startTime = timestamp;
  const delta = timestamp - startTime;
  score = delta / 1000;

  ctx.clearRect(0, 0, WIDTH, HEIGHT);

  if (!gameOver) {
    // spawn asteroids
    if (asteroidTimer++ > spawnInterval) {
      spawnAsteroid();
      asteroidTimer = 0;
    }
    ship.update();
    updateAsteroids();
    ship.draw();
    drawAsteroids();
    drawScore();
    requestAnimationFrame(loop);
  } else {
    ctx.fillStyle = '#f00';
    ctx.font = '30px sans-serif';
    ctx.fillText('Game Over', WIDTH / 2 - 80, HEIGHT / 2);
    drawScore();
  }
}

// Input handling
document.addEventListener('keydown', e => {
  if (e.key === 'ArrowLeft') ship.moveLeft = true;
  if (e.key === 'ArrowRight') ship.moveRight = true;
});

document.addEventListener('keyup', e => {
  if (e.key === 'ArrowLeft') ship.moveLeft = false;
  if (e.key === 'ArrowRight') ship.moveRight = false;
});

requestAnimationFrame(loop);
